E")[3].Value);RenderMatch();UpdateLayout();Check(renderer.EmoteCount==bubbles&&matchEffectsCanvas.Children.Count==0,"Minimal remains silent for emote events");ApplyMode(false);RenderMatch();UpdateLayout();Check(renderer.EmoteCount==bubbles,"Minimal events never replay on returning to normal");
