   var hostRenderer=(OfficeMatchVisualEffects)matchEffects;var guestRenderer=(OfficeMatchVisualEffects)guest.matchEffects;int hostBubbles=hostRenderer.EmoteCount,guestBubbles=guestRenderer.EmoteCount;guest.DoMatch("emote",emote:HeroEmotes.Options("MAGE")[3].Value);PumpLan(()=>!guest.lanWaiting&&hostRenderer.EmoteCount==hostBubbles+1&&guestRenderer.EmoteCount==guestBubbles+1,"Non-active guest speech bubbles appear on both peers");
   match.Players[0].Mana=10;match.Players[0].Hand.Clear();int wing=Inject(match,"NEW1_030");Inject(match,"CS2_182");match.Summon(1,"VAN_CS2_182");PublishLan();PumpLan(()=>guest.match.Players[0].HandCount==2,"Deathwing fixture exposes hand count only");int hostEntrances=hostRenderer.EntranceCount,guestEntrances=guestRenderer.EntranceCount;DoMatch("play",wing);PumpLan(()=>hostRenderer.EntranceCount==hostEntrances+1&&guestRenderer.EntranceCount==guestEntrances+1,"Deathwing entrance is synchronized to both peers");Check(OfficeMatchVisualEffects.EntranceDurationMs==2000&&matchEffectsCanvas.Children.OfType<TextBlock>().Count(t=>t.Text=="火")==44,"Deathwing produces forty-four red fire glyphs for two seconds");var watch=Stopwatch.StartNew();PumpLan(()=>watch.ElapsedMilliseconds>=200,"Entrance reaches visible animation frame");Render(Path.Combine(folder,"86-deathwing-entrance.png"));Check(Width==548&&Height==474,"Entrance keeps standard office dimensions");PublishLan();PumpLan(()=>guest.match.VisualEvents.Count==match.VisualEvents.Count,"Repeat entrance snapshot arrives");UpdateLayout();Check(guestRenderer.EntranceCount==guestEntrances+1,"Repeated snapshots do not replay entrance");PumpLan(()=>watch.ElapsedMilliseconds>=2200,"Entrance clock expires");Check(!matchEffectsCanvas.Children.OfType<TextBlock>().Any(t=>t.Text=="火"),"Fire glyphs are removed after two seconds");Check(((TranslateTransform)shell.RenderTransform).X==0,"Two-second screen shake returns to rest");
   guest.SetFullEffects(false);int mutedEntrances=guestRenderer.EntranceCount;match.Players[0].Mana=10;wing=Inject(match,"NEW1_030");DoMatch("play",wing);PumpLan(()=>guest.match.AnimationPlaying,"Muted guest receives authoritative animation wait");Check(!CanMatchInput()&&!guest.CanMatchInput()&&guest.livePrompt.Text.Contains("正在播放动画"),"Both peers are locked and muted peer displays animation status");int revision=lanAuthority.Revision;var rejected=lanAuthority.Execute(1,new LanCommand{Kind="emote",Emote=HeroEmotes.Options("MAGE")[3].Value,Revision=revision,Session=lanSession});Check(!rejected.Success&&rejected.Message.Contains("播放动画")&&lanAuthority.Revision==revision,"Host rejects forged commands during entrance without state change");Check(guestRenderer.EntranceCount==mutedEntrances&&!guest.matchEffectsCanvas.Children.OfType<TextBlock>().Any(t=>t.Text=="火"),"Muted guest waits without displaying fire");PublishLan();PumpLan(()=>guest.match.AnimationPlaying,"Repeated waiting snapshot arrives");guest.Opacity=1;guest.Render(Path.Combine(folder,"87-muted-animation-wait.png"));guest.Opacity=0;guest.ApplyMode(true);int mutedRevision=lanAuthority.Revision;guest.DoMatch("emote",emote:HeroEmotes.Options("MAGE")[3].Value);Check(!guest.lanWaiting&&lanAuthority.Revision==mutedRevision&&guest.status.Text.Contains("禁用对话"),"Minimal blocks network dialogue requests");Check(guest.match.AnimationPlaying&&!guest.CanMatchInput()&&guest.livePrompt.Text.Contains("正在播放动画")&&guest.matchEffectsCanvas.Children.Count==0,"Switching to minimal cannot bypass shared animation lock");SetFullEffects(false);Check(match.AnimationPlaying&&!CanMatchInput(),"Disabling effects does not cancel an active shared wait");PumpLan(()=>!match.AnimationPlaying&&!guest.match.AnimationPlaying&&CanMatchInput(),"Both peers automatically unlock at animation end");
